require_once __DIR__.'/includes/bootstrap.php'; require_login();
$q=trim((string)($_GET['q']??''));
if (strlen($q)>100) $q=substr($q,0,100);
if ($q!=='') { $stmt=$pdo->prepare('SELECT * FROM students WHERE student_no LIKE ? OR full_name LIKE ? OR email LIKE ? OR course LIKE ? ORDER BY id DESC'); $term='%'.$q.'%'; $stmt->execute([$term,$term,$term,$term]); $students=$stmt->fetchAll(); }
else { $students=$pdo->query('SELECT * FROM students ORDER BY id DESC')->fetchAll(); }
$pageTitle='Students';$active='students';require __DIR__.'/includes/header.php';
?><section class="panel"><div class="panel-head"><div><h2>Student directory</h2><p>Manage, search, and update student information.</p></div><a class="btn primary" href="student_form.php">+ Add student</a></div><form class="search" method="get"><input type="search" name="q" value="<?=e($q)?>" placeholder="Search by name, ID, email or course..." aria-label="Search students"><button class="btn secondary">Search</button><?php if($q!==''):?><a class="btn ghost" href="students.php">Clear</a><?php endif;?></form><div class="table-wrap"><table><thead><tr><th>Student</th><th>Student ID</th><th>Course</th><th>Year</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($students as $s):?><tr><td><strong><?=e($s['full_name'])?></strong><small><?=e($s['email'])?></small></td><td><?=e($s['student_no'])?></td><td><?=e($s['course'])?></td><td>Year <?=e($s['year_level'])?></td><td><span class="pill <?=strtolower($s['status'])?>"><?=e($s['status'])?></span></td><td class="actions"><a class="action-link" href="student_form.php?id=<?=e($s['id'])?>">Edit</a><form method="post" action="delete_student.php" onsubmit="return confirm('Delete this student permanently?');"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($s['id'])?>"><button class="delete-link">Delete</button></form></td></tr><?php endforeach;?><?php if(!$students):?><tr><td colspan="6" class="empty">No matching students found.</td></tr><?php endif;?></tbody></table></div><div class="table-foot">Showing <?=count($students)?> student(s)</div></section><?php require __DIR__.'/includes/footer.php';?>